namespace Engine.Factories;

using System;
using System.Linq;
using System.IO;
using System.Xml;
using Engine.Models;
using Engine.Actions;
using Engine.Shared;

public static class ItemFactory
{
    // Resolved against the folder holding the .exe, not the current working directory,
    // so the game and the tests find the data file wherever they are launched from.
    private static readonly string GAME_DATA_FILENAME =
        Path.Combine(AppContext.BaseDirectory, "GameData", "GameItems.xml");

    private static readonly List<GameItem> _standardGameItems = new List<GameItem>();

    static ItemFactory()
    {
        if (!File.Exists(GAME_DATA_FILENAME))
        {
            throw new FileNotFoundException($"Missing data file: {GAME_DATA_FILENAME}");
        }

        XmlDocument data = new XmlDocument();
        data.LoadXml(File.ReadAllText(GAME_DATA_FILENAME));

        // XPath is case sensitive - these must match the element names in GameItems.xml exactly.
        LoadItemsFromNodes(data.SelectNodes("/GameItems/Weapons/Weapon"));
        LoadItemsFromNodes(data.SelectNodes("/GameItems/HealingItems/HealingItem"));
        LoadItemsFromNodes(data.SelectNodes("/GameItems/MiscellaneousItems/MiscellaneousItem"));
    }

    public static GameItem CreateGameItem(int itemTypeId)
    {
        GameItem? standardItem = _standardGameItems.FirstOrDefault(item => item.ItemTypeId == itemTypeId);
        if(standardItem == null)
        {
            throw new ArgumentException($"ItemTypeId '{itemTypeId}' does not exist", nameof(itemTypeId));
        }
        return standardItem.Clone();
    }
    public static string ItemName(int id)
    {
        return _standardGameItems.FirstOrDefault(i => i.ItemTypeId == id)?.Name ?? "";
    }
    private static void LoadItemsFromNodes(XmlNodeList? nodes)
    {
        if(nodes == null)
        {
            return;
        }
        foreach(XmlNode node in nodes)
        {
            GameItem.ItemCategory itemCategory = DetermineItemCategory(node.Name);
            GameItem gameItem = new GameItem(
                itemCategory,
                node.AttributeAsInt("ID"),
                node.AttributeAsString("Name"),
                node.AttributeAsInt("Price"),
                itemCategory == GameItem.ItemCategory.Weapon
            );

            switch (itemCategory)
            {
                case GameItem.ItemCategory.Weapon:
                    gameItem.Action = new AttackWithWeapon(gameItem,
                        node.AttributeAsInt("MinimumDamage"),
                        node.AttributeAsInt("MaximumDamage"));
                    break;
                case GameItem.ItemCategory.Consumable:
                    gameItem.Action = new Heal(gameItem,
                        node.AttributeAsInt("HitPointsToHeal"));
                    break;
            }

            _standardGameItems.Add(gameItem);
        }
    }
    private static GameItem.ItemCategory DetermineItemCategory(string itemType)
    {
        switch (itemType)
        {
            case "Weapon":
                return GameItem.ItemCategory.Weapon;
            case "HealingItem":
                return GameItem.ItemCategory.Consumable;
            default:
                return GameItem.ItemCategory.Miscellanous;
        }
    }
}

